/**
 * Public half of the vendor licence-signing key. Generated by `npm run license:keygen`.
 *
 * IS_DEV_KEY = true means this is the development key whose private half is committed in
 * tools/license/dev-private-key.pem — anyone can forge licences for it. The Windows release
 * build refuses to package a dev key; run `npm run license:keygen` before shipping.
 */
export const IS_DEV_KEY = true;
export const LICENSE_PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAbzGC+7kfWgq/fEPZndso22qjl2JOMV/3FsuEuPT5VIM=
-----END PUBLIC KEY-----`;
